    {
      "card_ids": ["C01"],
      "claim": "Ampicillin absolute oral bioavailability was 48.1 ± 19.3% in nonpregnant women, an absolute IV-comparison measurement clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Ciramadol oral bioavailability was 80 ± 7% in patients with cirrhosis, a high-transfer oral bioavailability measurement supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Proguanil absolute oral bioavailability is as high as 60% in humans, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    }
